def expanded_pages(slug, pages):
    result = []
    for page_index, page in enumerate(pages, 1):
        for before, zh, en, prompt in EXTRA_PAGES[slug]:
            if before == page_index:
                result.append((zh, en, prompt))
        result.append(page)
    return result

def main():
    out = ROOT / "content-drafts/richang"
    out.mkdir(parents=True, exist_ok=True)
    for order, (slug, title, subtitle, moral, moral_en, tags, pages, goal, reminder, questions, activity) in enumerate(BOOKS, 1):
        pages = expanded_pages(slug, pages)
        book = {
            "id": slug, "seriesId": "richang", "title": title, "subtitle": subtitle,
            "moral": {"zh": moral, "en": moral_en},
            "ageLabel": "4–8 岁", "publishedAt": "2026-10-01", "order": order,
            "comingSoon": True,
            "pages": [{"page": i, "zhText": zh, "enText": en, "illustrationPrompt": prompt} for i, (zh, en, prompt) in enumerate(pages, 1)],
            "metadata": {"category": "family-growth", "ageRange": {"min": 4, "max": 8}, "estimatedMinutes": 5, "languages": ["zh", "en"], "seriesId": "richang", "seriesOrder": order, "personalizationEnabled": False, "tags": ["日常系列", "生活智慧", "亲子共读", *tags], "featured": order <= 3, "bedtimeSuitable": True},
            "parentGuide": {"goal": goal, "reminder": reminder, "questions": questions, "activity": activity, "ageTips": {"age4to5": "先看表情和动作，说一说主人公的感受，再选一个小行动试试。", "age6to8": "讨论选择的原因和结果，也允许提出不同办法；联系自己经历过的一件小事。"}},
        }
        file = out / f"{slug}.json"
        if file.exists():
            existing = json.loads(file.read_text())
            if existing["book"].get("comingSoon") is not True or any(p.get("imageStatus") == "complete" for p in existing["book"]["pages"]):
                raise RuntimeError(f"Refusing to overwrite a completed book: {file}")
        file.write_text(json.dumps({"book": book, "imagePromptKit": {"globalStyle": STYLE, "characterConsistency": CHARACTERS, "negative": NEGATIVE}}, ensure_ascii=False, indent=2) + "\n")
    manifest = out / "local-audio.json"
    if not manifest.exists():
        manifest.write_text("{}\n")
    print(f"Created {len(BOOKS)} books, {sum(len(expanded_pages(b[0], b[6])) for b in BOOKS)} bilingual pages")

if __name__ == "__main__":
    main()
